if(type==='routeAdd'||type==='routeEdit'){const r=arg,editing=type==='routeEdit',existing=editing?s.routes.find(x=>x.id===r?.id):null;if(editing&&!existing)return 'Ruten finnes ikke.';if(!r||!s.cities.includes(r.city)||!G.GOODS[r.good]||s.rep<G.GOODS[r.good].rep||!G.CARRIERS[r.carrier]||!Number.isInteger(r.qty)||r.qty<1||r.qty>G.CARRIERS[r.carrier].cap)return 'Sjekk by, vare og mengde.';if(s.routes.some(x=>x.city===r.city&&x.good===r.good&&(!editing||x.id!==r.id)))return 'Du har allerede en rute for varen i byen.';if(!editing&&s.routes.length>=1+s.managers*2)return 'Du trenger en driftsleder for flere ruter.';if(editing){Object.assign(existing,r);msg='Ruten er oppdatert.';}else{s.routes.push({...r,id:s.nextRoute++,active:true,last:'Venter på første oppgjør'});msg='Fast rute opprettet. Innkjøp, transport og salg skjer automatisk hver uke.';}}
else if(type==='routeToggle'){const r=s.routes.find(x=>x.id===i);if(!r)return 'Ruten finnes ikke.';r.active=!r.active;msg=r.active?'Ruten er aktiv.':'Ruten er pauset.';}
